# Task Dashboard API Client & React Query Hooks

Complete TypeScript implementation with authentication, retries, pagination, optimistic updates, and tests.

## Project Structure

```
src/
├── api/
│   ├── client.ts          # Core HTTP client
│   ├── auth.ts            # Auth token management
│   ├── tasks.ts           # Task endpoints
│   └── types.ts           # API types
├── hooks/
│   ├── useTasks.ts        # Query hooks
│   ├── useTaskMutations.ts
│   └── useAuth.ts
├── lib/
│   └── queryClient.ts     # Query client setup
├── test/
│   ├── client.test.ts
│   └── hooks.test.tsx
└── index.ts
```

---

## 1. Types (`src/api/types.ts`)

```typescript
// src/api/types.ts

export type TaskStatus = 'todo' | 'in_progress' | 'done' | 'archived';
export type TaskPriority = 'low' | 'medium' | 'high' | 'urgent';

export interface Task {
  id: string;
  title: string;
  description: string | null;
  status: TaskStatus;
  priority: TaskPriority;
  dueDate: string | null;
  assigneeId: string | null;
  projectId: string;
  createdAt: string;
  updatedAt: string;
  tags: string[];
}

export interface CreateTaskInput {
  title: string;
  description?: string;
  status?: TaskStatus;
  priority?: TaskPriority;
  dueDate?: string | null;
  assigneeId?: string | null;
  projectId: string;
  tags?: string[];
}

export interface UpdateTaskInput {
  title?: string;
  description?: string | null;
  status?: TaskStatus;
  priority?: TaskPriority;
  dueDate?: string | null;
  assigneeId?: string | null;
  tags?: string[];
}

export interface Paginated<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
  hasMore: boolean;
}

export interface TaskQueryParams {
  page?: number;
  pageSize?: number;
  status?: TaskStatus;
  priority?: TaskPriority;
  projectId?: string;
  search?: string;
  sortBy?: 'createdAt' | 'dueDate' | 'priority' | 'title';
  sortOrder?: 'asc' | 'desc';
}

